conversion-before-next-argument.source:
using symbol "std:io" @print;
using "std:exceptions" NullPointerException;
unit cm; unit m;
conversion function convert(x::f64(cm))::f64(m) throws NullPointerException {
  ptr p::f64 = null; m(p)
}
proc later()->f64 {behave @print(999); 0.0}
function consume(x::f64(m*), later::f64)->void {}
try {consume(cm(1.0),later())} catch(e::const NullPointerException){behave @print(1)};

reference-fields-relocation.harness:
#undef cod_lang_region_free
#include <cassert>
#include <cstring>
extern "C" void cod_lang_region_free(void *owner) {
  if (!owner) return;
  auto &original=*static_cast<CoDRegion *>(owner);
  const auto used=original.occupation();
  const auto offset=cod_lang_region_root(owner);
  CoDRegionOwner relocated(4096);
  std::memcpy(static_cast<void *>(&*relocated),owner,used);
  cod_lang_region_release(owner);
  auto *base=reinterpret_cast<const std::byte *>(&*relocated)+offset;
  const auto word=[](const std::byte *p){std::int64_t v;std::memcpy(&v,p,8);return v;};
  assert(word(base)==13 && word(base+8)==0);
  assert(base+16+word(base+16)==base);
  const auto *link=base+24;
  assert(word(link)==0);
  assert(link+8+word(link+8)==base);
  assert(link+16+word(link+16)==base);
  std::printf("{\"scalar_and_object_references_relocated\":true,\"original_released\":true,\"bytes\":%llu}\n",static_cast<unsigned long long>(used));
}

npe-cleanup.source:
using symbol "std:io" @print;
using "std:exceptions" NullPointerException;
data Node {value::i64; ptr next::Node;}
proc fail()->void throws NullPointerException {
 owned region temporary::Node <- make Node(capacity=512u64){value<-1;next=null};
 val unreachable <- root(temporary).next.value;
 {}
}
try {fail()} catch(e::const NullPointerException){behave @print(1)} finally {behave @print(2)};

npe-cleanup.harness:
#undef cod_lang_region_free
#undef cod_lang_print_i64
#include <cassert>
static unsigned released=0;
extern "C" void cod_lang_region_free(void *owner) {if(owner){++released;cod_lang_region_release(owner);}}
extern "C" void cod_lang_print_i64(std::int64_t value) {
 assert(released==1 && !cod_causes);
 cod_lang_trace_i64(value);
 if(value==2) std::puts("{\"released_before_npe_catch\":true,\"released_once\":1,\"finally_ran\":true,\"no_chain_allocation\":true}");
}
